// Token keys and allowed origins per tenant (UX-077 criteria 1, 2 and 4, and the origin half of 3;
// 05 §3.1, §4; PRO-010). The registry is in memory, and every key here is generated by the test.
// The administration API does not exist yet (UX-076), so these tests drive the registry that the
// seed and the operator commands write to.
import { createHmac, randomUUID, type KeyObject } from 'node:crypto';
import { uuid7 } from '@docedit/model';
import { describe, expect, it } from 'vitest';
import { b64url, signJws, type Algorithm } from '../../src/control-plane/jwt.ts';
import { MemoryTenantRegistry } from '../../src/control-plane/tenants.ts';
import { signingKey, TokenService } from '../../src/control-plane/tokens.ts';
import { MemoryUserDirectory } from '../../src/control-plane/users.ts';
import { hostKey } from './support.ts';

const SERVICE = 'https://docs.example.test';

function setup() {
  const now = Date.now();
  const registry = new MemoryTenantRegistry(() => now);
  const users = new MemoryUserDirectory();
  const tokens = new TokenService({
    registry,
    users,
    serviceId: SERVICE,
    signing: signingKey(undefined, 'svc'),
    now: () => now,
  });
  const doc = uuid7();
  const sign = (key: { kid: string; alg: Algorithm; privateKey: KeyObject }, tid: string) => {
    const iat = Math.floor(now / 1000);
    return signJws(
      { alg: key.alg, typ: 'JWT', kid: key.kid },
      {
        iss: 'host',
        aud: SERVICE,
        iat,
        exp: iat + 300,
        jti: uuid7(),
        tid,
        sub: 'u-1',
        docs: { [doc]: 'editor' },
      },
      key.privateKey,
    );
  };
  return { registry, users, tokens, sign };
}

describe('UX-077 criterion 1: a registered key set verifies its own tenant only', () => {
  it('accepts tokens of a key registered for the tenant, and refuses the same key under another tenant', async () => {
    const { registry, tokens, sign } = setup();
    const a = randomUUID();
    const b = randomUUID();
    await registry.putTenant(a, 'a');
    await registry.putTenant(b, 'b');
    const host = hostKey('ES256');
    await registry.addKey(a, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
    await expect(tokens.verifyUser(sign(host, a))).resolves.toMatchObject({ tenant: a });
    // The key is not registered for b, so a token of b signed with it is refused.
    await expect(tokens.verifyUser(sign(host, b))).rejects.toMatchObject({
      code: 'unauthenticated',
    });
    // The same key registered for b verifies b's tokens, and a's still verify.
    await registry.addKey(b, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
    await expect(tokens.verifyUser(sign(host, b))).resolves.toMatchObject({ tenant: b });
    await expect(tokens.verifyUser(sign(host, a))).resolves.toMatchObject({ tenant: a });
  });

  it('accepts only the allow-list algorithms (ES256, EdDSA, RS256) when registering a key', async () => {
    const { registry } = setup();
    const t = randomUUID();
    await registry.putTenant(t, 't');
    for (const alg of ['ES256', 'EdDSA', 'RS256'] as const) {
      const k = hostKey(alg);
      await expect(
        registry.addKey(t, { kid: k.kid, use: 'user', alg, jwk: k.jwk }),
      ).resolves.toMatchObject({ alg });
    }
  });

  it('refuses a symmetric key and an algorithm outside the allow-list at registration', async () => {
    const { registry } = setup();
    const t = randomUUID();
    await registry.putTenant(t, 't');
    const pub = hostKey('ES256');
    const symmetric = { kty: 'oct', k: 'c2VjcmV0LXNlY3JldC1zZWNyZXQ' };
    // A symmetric key under each allow-listed algorithm name, and an unsupported algorithm.
    for (const [alg, jwk] of [
      ['HS256', symmetric],
      ['ES256', symmetric],
      ['RS256', symmetric],
      ['PS256', pub.jwk],
      ['none', pub.jwk],
    ] as const) {
      await expect(
        registry.addKey(t, { kid: `bad-${alg}`, use: 'user', alg: alg as Algorithm, jwk }),
      ).rejects.toThrow();
    }
    expect(await registry.keys(t, 'user')).toEqual([]);
  });

  it('refuses an HS256 token signed with the registered public key as its secret', async () => {
    const { registry, tokens } = setup();
    const t = randomUUID();
    await registry.putTenant(t, 't');
    const host = hostKey('ES256');
    await registry.addKey(t, { kid: host.kid, use: 'user', alg: 'ES256', jwk: host.jwk });
    const iat = Math.floor(Date.now() / 1000);
    const header = b64url(JSON.stringify({ alg: 'HS256', typ: 'JWT', kid: host.kid }));
    const payload = b64url(
      JSON.stringify({
        iss: 'h',
        aud: SERVICE,
        iat,
        exp: iat + 60,
        jti: 'j',
        tid: t,
        sub: 's',
        docs: { [uuid7()]: 'owner' },
      }),
    );
    const mac = createHmac('sha256', JSON.stringify(host.jwk))
      .update(`${header}.${payload}`)
      .digest('base64url');
    await expect(tokens.verifyUser(`${header}.${payload}.${mac}`)).rejects.toMatchObject({
      code: 'unauthenticated',
    });
  });
});

describe('UX-077 criterion 2: rotation overlap, and a removed key is refused at once', () => {
  it('verifies tokens of both keys during the overlap and refuses the removed key at once', async () => {
    const { registry, tokens, sign } = setup();
    const t = randomUUID();
    await registry.putTenant(t, 't');
    const oldKey = hostKey('ES256', 'old-1');
    const newKey = hostKey('ES256', 'new-1');
    await registry.addKey(t, { kid: oldKey.kid, use: 'user', alg: 'ES256', jwk: oldKey.jwk });
    // The new key is added before the old is removed: both verify.
    await registry.addKey(t, { kid: newKey.kid, use: 'user', alg: 'ES256', jwk: newKey.jwk });
    await expect(tokens.verifyUser(sign(oldKey, t))).resolves.toMatchObject({ tenant: t });
    await expect(tokens.verifyUser(sign(newKey, t))).resolves.toMatchObject({ tenant: t });
    // Removing the old key refuses its tokens immediately; the new key's still verify.
    expect(await registry.removeKey(t, oldKey.kid)).toBe(true);
    await expect(tokens.verifyUser(sign(oldKey, t))).rejects.toMatchObject({
      code: 'unauthenticated',
    });
    await expect(tokens.verifyUser(sign(newKey, t))).resolves.toMatchObject({ tenant: t });
  });
});

describe("UX-077 criterion 4 (registry half): one tenant never lists another tenant's keys or origins", () => {
  it('scopes keys and origins to the tenant they were registered for', async () => {
    const { registry } = setup();
    const a = randomUUID();
    const b = randomUUID();
    await registry.putTenant(a, 'a');
    await registry.putTenant(b, 'b');
    const ka = hostKey('ES256');
    const kb = hostKey('EdDSA');
    await registry.addKey(a, { kid: ka.kid, use: 'user', alg: 'ES256', jwk: ka.jwk });
    await registry.addKey(b, { kid: kb.kid, use: 'user', alg: 'EdDSA', jwk: kb.jwk });
    await registry.addOrigin(a, 'https://a.example.test');
    await registry.addOrigin(b, 'https://b.example.test');
    expect((await registry.keys(a, 'user')).map((k) => k.kid)).toEqual([ka.kid]);
    expect((await registry.keys(b, 'user')).map((k) => k.kid)).toEqual([kb.kid]);
    expect(await registry.origins(a)).toEqual(['https://a.example.test']);
    expect(await registry.origins(b)).toEqual(['https://b.example.test']);
  });
});

describe('UX-077 criterion 3 (list half): origins are normalised and only listed ones are registered', () => {
  it('stores an origin in its canonical form and refuses one with a path or credentials', async () => {
    const { registry } = setup();
    const t = randomUUID();
    await registry.putTenant(t, 't');
    await registry.addOrigin(t, 'https://App.Example.test:443');
    expect(await registry.origins(t)).toEqual(['https://app.example.test']);
    expect(await registry.originRegistered('https://app.example.test')).toBe(true);
    expect(await registry.originRegistered('https://nobody.example.test')).toBe(false);
    await expect(registry.addOrigin(t, 'https://a.example.test/path')).rejects.toThrow();
    await expect(registry.addOrigin(t, 'https://user:pw@a.example.test')).rejects.toThrow();
    await expect(registry.addOrigin(t, 'ftp://a.example.test')).rejects.toThrow();
  });
});
